package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where
 * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} the
 * upper-cased first three letters of the last name, and {@code NNNN} a per-city 4-digit
 * zero-padded sequence equal to one more than the number of owners already in that city
 * (e.g. {@code SYD-SMI-0007}).
 */
public class AssignOwnerCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String cityPrefix = prefix(owner.getCity());
        String lastPrefix = prefix(owner.getLastName());
        int sequence = 1 + (int) ownerRepository.findAll().stream()
                .filter(existing -> owner.getCity() != null
                        && owner.getCity().equalsIgnoreCase(existing.getCity()))
                .count();
        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
    }

    private static String prefix(String value) {
        String s = value == null ? "" : value;
        return s.substring(0, Math.min(3, s.length())).toUpperCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName",
            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials",
            expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
                    + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
    @Mapping(target = "locality",
            expression = "java(org.springframework.samples.petclinic.rest.function.common"
                    + ".Localities.of(owner.getCity(), owner.getPostcode()))")
    @Mapping(target = "checkDigit",
            expression = "java(org.springframework.samples.petclinic.rest.function.common"
                    + ".Luhn.checkDigit(owner.getCustomerCode()))")
    @Mapping(target = "membershipNumber",
            expression = "java(owner.getCustomerCode() + \"-M\" "
                    + "+ String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
    @Mapping(target = "identityKey",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner"
                    + ".IdentityKey.ofOwner(owner))")
    @Mapping(target = "contactPreference",
            expression = "java(hasEmail(owner) ? \"EMAIL\" : \"PHONE\")")
    @Mapping(target = "membershipLevel",
            expression = "java(Math.min(3, 1 "
                    + "+ (hasEmail(owner) ? 1 : 0) "
                    + "+ (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0 ? 1 : 0)))")
    OwnerDto toOwnerDto(Owner owner);

    /** Whether the owner has a usable email address. */
    default boolean hasEmail(Owner owner) {
        return owner.getEmail() != null && !owner.getEmail().isBlank();
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
